def transform(grid):
    # Mark single-cell breaks in a one-color rectangular outline with red (2).
    g = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    candidates = [(n, v) for v, n in counts.items() if v != background]
    if not candidates:
        return g
    color = min(candidates)[1]
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    # Bridge short gaps between successive occurrences along each row and
    # column, using marker color 2. Longer gaps are left untouched.
    h, w = len(grid), len(grid[0])
    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] == color]
        for a, b in zip(marks, marks[1:]):
            if b - a > 1:
                for c in range(a + 1, b):
                    g[r][c] = 2
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == color]
        for a, b in zip(marks, marks[1:]):
            if b - a > 1:
                for r in range(a + 1, b):
                    g[r][c] = 2
    return g

